    # from its host, put 17-34 dB of hiss above 2 kHz on every attack
    chiff_volume = 0.0
    # its release, as the principal's: a narrower spread, no lean (22 pipes
    # of the Gedakt and Pommer: 0.55 -> 0.36 octaves)
    release_band_mu = 0.0
