    bloom_gain = 1.654
    bloom_swell = 0.8055
    bloom_gain_slope = 1.121
    band_trim_db = ((354, 5.8), (707, 14.5), (1414, -7.0), (2828, -1.9), (5657, -3.8), (11314, -7.6))
