    bloom_gain = 3.93429
    bloom_seconds = 0.0168182
    bloom_center_hz = 3224.36
    bloom_octaves = 2.04106
    bloom_swell = 0.586091
    bloom_gain_slope = 0.952862
    chiff_volume = 1.6399
    chiff_width = 0.265716
    band_trim_db = ((354, 11.3), (707, 8.4), (1414, -2.5), (2828, -4.6), (5657, -5.6), (11314, -6.9))
